import {guideCardsHTML} from './lens-guides.js';
const lensTypes=[{"title": "Прогрессивные", "number": "01", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"40\" cy=\"40\" r=\"27\"/><path d=\"M18 26h44M13 42h54M21 57h38\"/><path d=\"M40 16v49\" stroke-dasharray=\"3 5\" opacity=\".4\"/></svg></div>", "description": "3 зоны в одних очках: даль, средняя дистанция, близь. Гарантированная адаптация."}, {"title": "Blue Control", "number": "02", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"16\" y=\"19\" width=\"38\" height=\"30\" rx=\"5\"/><path d=\"M23 56h29M36 49v7\"/><path d=\"m53 35 14 6v12c0 8-7 12-14 15-7-3-14-7-14-15V41Z\" fill=\"#f6eee1\"/><path d=\"m47 51 4 4 9-10\"/></svg></div>", "description": "Защита ваших глаз от всех современных гаджетов."}, {"title": "Фотохромные линзы", "number": "03", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"40\" cy=\"40\" r=\"21\"/><path d=\"M40 19a21 21 0 0 1 0 42Z\" fill=\"#b9935b\" fill-opacity=\".35\"/><path d=\"M40 8v5M40 67v5M8 40h5M67 40h5M17 17l4 4M59 59l4 4M17 63l4-4M59 21l4-4\"/></svg></div>", "description": "Хамелеоны."}, {"title": "Солнцезащитные линзы", "number": "04", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10 35h60M12 36l4 17c2 7 17 8 21-1l2-13h2l2 13c4 9 19 8 21 1l4-17\"/><path d=\"M17 36h18l-2 15c-3 6-13 5-15 0ZM45 36h18l-2 15c-2 5-12 6-15 0Z\" fill=\"#b9935b\" fill-opacity=\".35\"/><path d=\"M58 11v11M53 16h10\"/></svg></div>", "description": "С диоптриями и без."}, {"title": "Офисные линзы", "number": "05", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"14\" y=\"17\" width=\"52\" height=\"35\" rx=\"5\"/><path d=\"M30 61h20M40 52v9M24 28h32M24 35h20\"/><path d=\"M51 39h18v26H51Z\" fill=\"#f6eee1\"/><path d=\"M55 46h10M55 52h10M55 58h6\"/></svg></div>", "description": "Для работы на средних и ближних дистанциях."}, {"title": "Линзы для вождения", "number": "06", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m19 31 6-14h30l6 14M18 32h44v25H18ZM22 57v7M58 57v7M31 48h18\"/><path d=\"M21 39h8v5h-8ZM51 39h8v5h-8\" fill=\"#b9935b\" fill-opacity=\".45\"/><path d=\"M7 34l6 3M5 43h8M7 52l6-3M67 37l6-3M67 43h8M67 49l6 3\"/></svg></div>", "description": "Блокировка от встречных фар с фильтром HD высокой чёткости."}, {"title": "Линзы для контроля миопии для детей", "number": "07", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"25\" cy=\"44\" r=\"12\"/><circle cx=\"55\" cy=\"44\" r=\"12\"/><path d=\"M37 44h6M12 42l-4-7M68 42l4-7M40 29V13M40 25c-11 0-13-6-13-11 8 0 13 3 13 11ZM40 21c10 0 13-6 13-11-8 0-13 3-13 11Z\"/></svg></div>", "description": "Предупреждение падения зрения у детей."}, {"title": "Поляризационные линзы", "number": "08", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"40\" cy=\"40\" r=\"26\"/><path d=\"m23 54 31-31M18 43l25-25M34 62l28-28\"/><path d=\"M6 28h8M4 40h10M6 52h8M66 40h10\" stroke-dasharray=\"2 3\"/></svg></div>", "description": "Антибликовые очки."}, {"title": "(А)Сферические", "number": "09", "art": "<div class=\"lens-art\" aria-hidden=\"true\"><svg viewBox=\"0 0 80 80\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><ellipse cx=\"40\" cy=\"40\" rx=\"24\" ry=\"29\"/><ellipse cx=\"40\" cy=\"40\" rx=\"12\" ry=\"29\"/><path d=\"M16 40h48M20 26h40M20 54h40M65 13v12M59 19h12\"/></svg></div>", "description": "Лёгкость и утончённость."}];
const lensGuideLinks=[
 ['Прогрессивные','Даль, средние расстояния и близь в одной паре. Для комфортного использования важны измерения и привыкание.','/lenses/progressivnye-linzy'],
 ['Blue Control','Фильтр части синего света. При работе за экраном в первую очередь важны коррекция, рабочее расстояние и перерывы.','/lenses/kak-vybrat-linzy#screen'],
 ['Фотохром','Изменяют затемнение в зависимости от условий освещения. Возможность работы в автомобиле уточняют для конкретной серии.','/lenses/kak-vybrat-linzy#sun'],
 ['Солнцезащитные','Постоянная тонировка с диоптриями или без. Цвет, степень затемнения и УФ-защиту оценивают отдельно.','/lenses/kak-vybrat-linzy#sun'],
 ['Офисные','Для близких и средних рабочих расстояний: документов, монитора и помещения. Диапазон зависит от конструкции.','/lenses/kak-vybrat-linzy#screen'],
 ['Вождения','Подбирают под дневное или вечернее вождение. Проверка зрения и свойства конкретной линзы важнее рекламного названия.','/lenses/kak-vybrat-linzy#driving'],
 ['Контроль миопии','Специальные конструкции для детей рассматривают с офтальмологом. Подбор и наблюдение проходят по индивидуальному плану.','/lenses/kak-vybrat-linzy#children'],
 ['Поляризация','Уменьшают некоторые отражённые блики от воды и дороги. Проверьте видимость экранов и приборов.','/lenses/kak-vybrat-linzy#sun'],
 ['Асферические','Особая форма поверхности позволяет оптимизировать профиль линзы. Результат зависит от рецепта, материала и центровки.','/lenses/kak-vybrat-linzy#surface']
];
lensTypes.forEach((lens,index)=>{lens.description=lensGuideLinks[index][1];lens.guide=lensGuideLinks[index][2];});
export function lensesPageHTML(){return `<section class="lenses-page wrap"><nav class="breadcrumbs" aria-label="Хлебные крошки"><a href="/">Главная</a><span aria-hidden="true">/</span><span aria-current="page">Линзы</span></nav><header class="lenses-intro"><p class="eyebrow">ИНДИВИДУАЛЬНЫЙ ПОДБОР</p><h1>Линзы для вашей жизни</h1><p>Подберём линзы с диоптриями и без — под ваши потребности и привычные задачи.</p><span class="lenses-mobile-hint">Нажмите на название, чтобы узнать больше</span></header>${guideCardsHTML()}<div class="lenses-types">${lensTypes.map(lens=>`<details class="lens-detail" name="lens-types"><summary><span class="lens-detail-number">${lens.number}</span>${lens.art}<h2>${lens.title}</h2><span class="lens-detail-toggle" aria-hidden="true">+</span></summary><div class="lens-detail-body"><p>${lens.description}</p><a class="lens-guide-link" href="${lens.guide}">Что важно при выборе ↗</a><button class="lens-detail-booking" data-booking aria-label="Записаться на подбор: ${lens.title}">Подобрать линзы <span aria-hidden="true">↗</span></button></div></details>`).join('')}</div><div class="lenses-page-cta"><h2>Поможем выбрать подходящие линзы</h2><p>Обсудим ваши задачи и подберём линзы в салоне.</p><button class="button" data-booking>Записаться на подбор линз</button></div></section>`;}
const desktop=typeof matchMedia==='function'?matchMedia('(min-width:901px)'):null;
export function arrangeLensDetails(){document.querySelectorAll('.lenses-types details').forEach(el=>{el.removeAttribute('name');el.open=desktop.matches;if(!desktop.matches)el.setAttribute('name','lens-types');});}
desktop?.addEventListener('change',arrangeLensDetails);
if(typeof document!=='undefined')document.addEventListener('click',event=>{if(desktop.matches&&event.target.closest('.lens-detail summary'))event.preventDefault();});
